// Navigation with conditional rendering
import { Link } from 'react-router-dom';

function NavBar() {
  const { isAuthenticated } = useAuth();

  return (
    <nav>
      <Link to="/">Home</Link>
      {!isAuthenticated && <Link to="/login">Login</Link>}
      {isAuthenticated && <Link to="/dashboard">Dashboard</Link>}
    </nav>
  );
}

